// 核心函数：构造URL
function apiurl(speakText, speakSpeed, apiurl) {
    let info = this.source.getLoginInfoMap();
    let api = apiurl || info["api"];
    let fyr = info["发言人"];
    let fyrk = fyrM[fyr];
    let fg = info["风格"];
    let fgk = styleM[fg];
    // 语速转换：Legado的speakSpeed 1-20，映射到-100~100，公式 (speakSpeed-10)*10
    let rate = (speakSpeed - 10) * 10;
    let pitch = 0; // 音调默认0

    // 根据API地址选择不同的参数格式
    if (api.includes("okraworks.cn")) {
        // 格式：?text=...&voice=...&rate=...&pitch=...
        return `${api}?text=${encodeURIComponent(speakText)}&voice=${fyrk}&rate=${rate}&pitch=${pitch}`;
    } else if (api.includes("zwei.de.eu.org") || api.includes("libretts.is-an.org")) {
        // 格式：?t=...&v=...&r=...&p=...
        return `${api}?t=${encodeURIComponent(speakText)}&v=${fyrk}&r=${rate}&p=${pitch}`;
    } else if (api.includes("wangwangit.com")) {
        // 这个接口可能是POST，但范例中使用GET，我们仍用GET，但参数格式可能需要调整
        // 暂且使用常见的v=音色&text=文字
        return `${api}?text=${encodeURIComponent(speakText)}&voice=${fyrk}&speed=${rate}`;
    } else {
        // 其他未知接口，尝试通用格式 ?t=...&v=...&r=...&p=...
        return `${api}?t=${encodeURIComponent(speakText)}&v=${fyrk}&r=${rate}&p=${pitch}`;
    }
}

